#[cfg(test)] mod regression {use super::*;
#[test] fn failures_are_in_numerator() { assert_eq!(metrics(&[Some(70),Some(30)], &[Some(false),Some(true)]),Ok(Some((100,1)))); }
#[test] fn unknown_cost_keeps_whole_ratio_unknown() { assert_eq!(metrics(&[None,Some(30)], &[Some(false),Some(true)]),Ok(None)); }
#[test] fn no_success_has_no_ratio() { assert_eq!(metrics(&[Some(10)], &[Some(false)]),Ok(None)); }
#[test] fn outcome_unknown_and_length_invalid() {
 assert_eq!(metrics(&[Some(2)], &[None]),Ok(None));
 assert_eq!(metrics(&[], &[Some(true)]),Err("length"));
}
#[test] fn wide_sum_and_known_zero() {
 assert_eq!(metrics(&[Some(u64::MAX),Some(u64::MAX)], &[Some(true),Some(false)]),Ok(Some((36893488147419103230,1))));
 assert_eq!(metrics(&[Some(0)], &[Some(true)]),Ok(Some((0,1))));
}
}
